import networkx as nx
from itertools import combinations, product

def count_dist_2_pairs(G):
    count = 0
    nodes = list(G.nodes())
    for u, v in combinations(nodes, 2):
        try:
            if nx.shortest_path_length(G, source=u, target=v) == 2:
                count += 1
        except nx.NetworkXNoPath:
            pass
    return count

def max_dist_2_pairs(n):
    max_pairs = 0
    # We can't iterate over all graphs for n > 7. 
    # But we can try some common graph types.
    # 1. Complete bipartite graphs
    for m in range(1, n // 2 + 1):
        G = nx.complete_bipartite_graph(m, n - m)
        max_pairs = max(max_pairs, count_dist_2_pairs(G))

    # 2. Random graphs (this is a heuristic)
    import random
    for _ in range(1000):
        # Try random number of edges
        num_edges = random.randint(0, n * (n - 1) // 2)
        G = nx.gnm_random_graph(n, num_edges)
        max_pairs = max(max_pairs, count_dist_2_pairs(G))

    return max_pairs

for n in range(3, 11):
    print(f"n={n}, max_pairs={max_dist_2_pairs(n)}, star_pairs={ (n-1)*(n-2)//2 }")
